package mz.bam.seeky.android;
import android.app.Application;import android.media.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.robolectric.shadows.util.DataSource;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,shadows={BackgroundPcmTest.Codec.class,BackgroundPcmTest.Extractor.class}) @LooperMode(LooperMode.Mode.PAUSED)
public class BackgroundPcmTest {
 @Implements(MediaCodec.class) public static class Codec extends ShadowMediaCodec {boolean format;static boolean waitedForInput;@Implementation protected int native_dequeueInputBuffer(long timeout){if(timeout!=0)waitedForInput=true;return super.native_dequeueInputBuffer(timeout);}@Implementation protected int native_dequeueOutputBuffer(MediaCodec.BufferInfo info,long timeout){if(!format){format=true;return MediaCodec.INFO_OUTPUT_FORMAT_CHANGED;}return super.native_dequeueOutputBuffer(info,timeout);}}
 @Implements(MediaExtractor.class) public static class Extractor extends ShadowMediaExtractor {@Implementation protected long getSampleTime(){return 0;}}
 File root;@Before public void setup()throws Exception{root=Files.createTempDirectory("background-pull-").toFile();Codec.waitedForInput=false;}
 File wav(String name,int frames)throws Exception{File file=new File(root,name);byte[] samples=new byte[frames*2];for(int n=0;n<samples.length;n+=2){short value=(short)(Math.sin(n*.01)*2000);samples[n]=(byte)value;samples[n+1]=(byte)(value>>8);}VoiceToolsTest.writeWav(file,samples);return file;}
 @Test public void aLongBackgroundIsNotFullyDecodedBeforeTheFirstNarrationChunk()throws Exception{File source=wav("long.wav",24000*60),voice=wav("voice.wav",2400),work=new File(root,"work");work.mkdirs();try(BackgroundPcm bg=BackgroundPcm.prepare(source,work,()->false,null)){assertEquals(0,bg.file.length());assertFalse(bg.complete);bg.mix(voice,new File(root,"first.wav"),0,20,()->false);assertTrue(bg.frames>=2402);assertTrue(bg.frames<24000*60);assertTrue(bg.file.length()<source.length()/10);assertFalse(bg.meta.exists());assertEquals(4800,WaveJoiner.inspect(new File(root,"first.wav")).length);}}
 @Test public void progressiveMixMatchesFullBackgroundAndLoopsAtTheRealEnd()throws Exception{File source=wav("track.wav",24000*4),voice=wav("voice.wav",24000),work=new File(root,"work");work.mkdirs();File raw=new File(root,"full.pcm");BackgroundWave.decode(source,raw,()->false);try(BackgroundPcm bg=BackgroundPcm.prepare(source,work,()->false,null)){for(int n=0;n<6;n++){File actual=new File(root,"actual-"+n+".wav"),expected=new File(root,"expected-"+n+".wav");bg.mix(voice,actual,n*24000L,25,()->false);BackgroundMixer.mix(voice,expected,raw,24000,1,n*24000L,25,()->false);assertArrayEquals(Files.readAllBytes(expected.toPath()),Files.readAllBytes(actual.toPath()));}assertTrue(bg.complete);assertTrue(bg.meta.exists());}try(BackgroundPcm cached=BackgroundPcm.prepare(source,work,()->false,null)){assertTrue(cached.complete);assertNull(cached.codec);assertNull(cached.output);}}
 @Test public void cancellingPreparationDoesNotMarkAPartialCacheComplete()throws Exception{File source=wav("track.wav",24000*10),work=new File(root,"work");work.mkdirs();AtomicBoolean cancelled=new AtomicBoolean();try(BackgroundPcm bg=BackgroundPcm.prepare(source,work,cancelled::get,null)){bg.ensure(1000);cancelled.set(true);try{bg.ensure(Long.MAX_VALUE);fail("Cancellation must be observed");}catch(InterruptedIOException expected){}assertFalse(bg.meta.exists());}try(BackgroundPcm retry=BackgroundPcm.prepare(source,work,()->false,null)){assertEquals(0,retry.frames);retry.ensure(1000);assertTrue(retry.frames>0);}}
 @Test public void compressedDecoderDrainsOutputWithoutBlockingForAnInputSlot()throws Exception{File source=new File(root,"source.audio");Files.write(source.toPath(),new byte[]{1,2,3,4});MediaFormat format=MediaFormat.createAudioFormat("audio/mpeg",24000,1);format.setLong(MediaFormat.KEY_DURATION,10000000);byte[] decoded=new byte[480000];for(int n=0;n<decoded.length;n++)decoded[n]=(byte)n;ShadowMediaExtractor.addTrack(DataSource.toDataSource(source.getPath()),format,decoded);File work=new File(root,"work");work.mkdirs();try(BackgroundPcm bg=BackgroundPcm.prepare(source,work,()->false,null)){bg.ensure(2400);assertTrue(bg.frames>=2400);assertFalse(Codec.waitedForInput);assertFalse(bg.complete);bg.ensure(Long.MAX_VALUE);assertTrue(bg.complete);assertEquals(decoded.length,bg.file.length());assertArrayEquals(decoded,Files.readAllBytes(bg.file.toPath()));}}
}
